#!/bin/sh
PATH=/usr/bin:/bin
export PATH
LC_ALL=C
export LC_ALL

if [ ! -r /proc/meminfo ]; then
    printf '%s\n' 'event_type=collector_error collection_status=error error_code=meminfo_unreadable'
    exit 0
fi

awk '
BEGIN {
    keys[1]="HugePages_Total"; keys[2]="HugePages_Free";
    keys[3]="HugePages_Rsvd";  keys[4]="HugePages_Surp";
    keys[5]="Hugepagesize";    keys[6]="Hugetlb";
}
{
    key=$1; sub(/:$/, "", key);
    for (i=1; i<=6; i++) if (key==keys[i]) value[key]=$2;
}
END {
    bad=0;
    for (i=1; i<=6; i++)
        if (!(keys[i] in value) || value[keys[i]] !~ /^[0-9]+$/) bad=1;
    if (bad) {
        print "event_type=collector_error collection_status=error error_code=missing_or_nonnumeric_meminfo_field";
    } else {
        printf "event_type=pool_sample collection_status=ok HugePages_Total=%s HugePages_Free=%s HugePages_Rsvd=%s HugePages_Surp=%s Hugepagesize_kB=%s Hugetlb_kB=%s\n", value["HugePages_Total"], value["HugePages_Free"], value["HugePages_Rsvd"], value["HugePages_Surp"], value["Hugepagesize"], value["Hugetlb"];
    }
}' /proc/meminfo
